package com.ultron.voice;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.hardware.camera2.*;import android.speech.*;import android.speech.tts.TextToSpeech;import java.util.*;
public class ListenService extends Service {
 SpeechRecognizer sr;TextToSpeech tts;Handler h=new Handler(Looper.getMainLooper());boolean active=false;boolean waiting=false;
 public void onCreate(){super.onCreate();NotificationChannel ch=new NotificationChannel("ultron","ULTRON listening",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);Notification n=new Notification.Builder(this,"ultron").setContentTitle("ULTRON AI is listening").setContentText("Tap app to stop").setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();startForeground(1,n);tts=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS)tts.setLanguage(Locale.US);});}
 public int onStartCommand(Intent i,int f,int id){active=true;listen();return START_NOT_STICKY;}
 void listen(){if(!active||waiting)return;h.post(()->{if(!active)return;if(!SpeechRecognizer.isRecognitionAvailable(this)){say("Speech recognition unavailable");return;}try{if(sr!=null)sr.destroy();sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float x){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}public void onError(int e){retry();}public void onResults(Bundle b){ArrayList<String> a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty())command(a.get(0).toLowerCase(Locale.ROOT));retry();}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-IN");sr.startListening(i);}catch(Exception e){retry();}});}
 void retry(){waiting=true;h.postDelayed(()->{waiting=false;listen();},1100);}
 void command(String s){if(!s.contains("ultron"))return;if(s.contains("youtube")){open("com.google.android.youtube");say("Opening YouTube");}else if(s.contains("whatsapp")){open("com.whatsapp");say("Opening WhatsApp");}else if(s.contains("torch")||s.contains("flashlight")){boolean off=s.contains("off")||s.contains("band");try{CameraManager c=getSystemService(CameraManager.class);for(String id:c.getCameraIdList()){if(Boolean.TRUE.equals(c.getCameraCharacteristics(id).get(CameraCharacteristics.FLASH_INFO_AVAILABLE))){c.setTorchMode(id,!off);break;}}say(off?"Torch off":"Torch on");}catch(Exception e){say("Torch not available or camera permission needed");}}else if(s.contains("time")||s.contains("waqt")){say("Time is "+new java.text.SimpleDateFormat("h:mm a",Locale.US).format(new Date()));}else say("Command not supported yet");}
 void open(String pkg){Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}else say("App not installed");}
 void say(String s){if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"ultron");}
 public void onDestroy(){active=false;h.removeCallbacksAndMessages(null);if(sr!=null)sr.destroy();if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
 public IBinder onBind(Intent i){return null;}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                 
